create table public.nexus_ai_quota (user_id uuid not null references auth.users(id) on delete cascade, day date not null, used integer not null check (used between 1 and 50), primary key(user_id,day)); alter table public.nexus_ai_quota enable row level security; revoke all on public.nexus_ai_quota from public, anon, authenticated; grant select,insert,update on public.nexus_ai_quota to service_role; create function public.nexus_consume_quota(p_user uuid) returns boolean language plpgsql security invoker set search_path='' as $$ declare n integer; begin insert into public.nexus_ai_quota as q(user_id,day,used) values(p_user,(now() at time zone 'UTC')::date,1) on conflict(user_id,day) do update set used=q.used+1 where q.used<50 returning used into n; return n is not null; end; $$; revoke all on function public.nexus_consume_quota(uuid) from public,anon,authenticated; grant execute on function public.nexus_consume_quota(uuid) to service_role;